export type BinarySource = "override" | "path" | "login-path" | "known-dir";

export type ChangeStatus = "added" | "modified" | "deleted" | "renamed";

export type ChatActionName = "rename" | "autotitle" | "pin" | "unpin" | "archive" | "unarchive" | "delete";

/**
 *  A saved chat image as the composer needs it: the vault-relative path (what the draft keeps and
 *  the chat note embeds) and the file name (the chip label).
 */
export type ChatImage = {
	path: string,
	name: string,
};

export type ChatSummary = {
	chatId: string,
	path: string,
	title: string,
	projectPath: string | null,
	sessionId: string | null,
	createdAt: number,
	updatedAt: number,
	turnCount: number,
	archived: boolean,
	pinned: boolean,
	/**  First user message, one line, for the history list and its search. */
	preview?: string | null,
	titleSource?: TitleSource,
};

/**
 *  Data types (`ContextRef`, `ProjectSource`) use `kind` as their discriminant; events and
 *  commands use `type`.
 */
export type ContextRef = { kind: "active-note"; path: string; inline: boolean } | { kind: "selection"; path: string; text: string; fromLine: number; toLine: number } | { kind: "note"; path: string } | { kind: "folder"; path: string } | { kind: "tag"; tag: string } | { kind: "property"; name: string; value: string | null } | { kind: "project-instructions"; path: string } | { kind: "project-source"; source: ProjectSource } | 
/**
 *  An image attached to the message (vault-relative path): sent to the model as a native
 *  image block and listed in the references footer. Pasted images live in the chat's hidden
 *  `assets/` folder (`images.rs`), an image from the sidebar is referenced where it is.
 */
{ kind: "image"; path: string };

export type DiffRow = {
	kind: DiffRowKind,
	/**  1-based; None on an added row. */
	oldLine: number | null,
	/**  1-based; None on a removed row. */
	newLine: number | null,
	text: string,
};

export type DiffRowKind = "context" | "add" | "del";

export type DiskSkill = {
	name: string,
	/**  One line, at most 300 characters; empty when the skill has none. */
	description: string,
	/**  `project` (the active project's folder), `vault` (the vault root) or `global` (the home). */
	scope: string,
	/**  Vault-relative path of the `SKILL.md`; the absolute path for a `global` skill. */
	path: string,
};

export type Effort = "low" | "medium" | "high" | "xhigh" | "max";

export type FileChange = {
	rows: DiffRow[],
	/**  `rows` stops early (very large diff). */
	truncated?: boolean,
	undo: UndoState,
} & FileChangeSummary;

/**  One changed file, as sent in `turn-changes` and stored in the chat note (paths and counts only). */
export type FileChangeSummary = {
	/**  Vault-relative, forward slashes. For a rename, the new path. */
	path: string,
	status: ChangeStatus,
	added: number,
	removed: number,
	/**  Renames only: where the file came from. */
	oldPath?: string | null,
	/**  Not shown as a diff: binary, too large, or not safely readable. Counts are 0. */
	noDiff?: boolean,
	/**
	 *  The sub-agent role that made the edit (`worker`; another sub-agent type as it is named),
	 *  shown as a small label on the card. Absent: the main agent. The first edit of the file in
	 *  the turn decides (the card's first-snapshot-wins rule).
	 */
	by?: string | null,
};

/**  What "Make project" would do to a folder, for the dialog's convert mode. */
export type FolderInspection = {
	path: string,
	name: string,
	isProject: boolean,
	hasProjectMd: boolean,
	hasAgentsMd: boolean,
	hasClaudeMd: boolean,
};

export type LoadedChat = {
	summary: ChatSummary,
	markdown: string,
};

export type Manifest = {
	entries: ManifestEntry[],
	/**  Sample paths that did not fit under [`MAX_LISTED_PATHS`]. */
	more: number,
	exclusions: string[],
	/**  Unrecognised entries, shown to the user and mentioned to the agent verbatim. */
	unsupported: string[],
	webUrls: string[],
	youtubeUrls: string[],
};

export type ManifestEntry = {
	/**  `folder`, `note`, `tag`, `property`, `url`. */
	kind: string,
	label: string,
	/**  `None` when the source could not be resolved (see `warning`). */
	count: number | null,
	samples: string[],
	warning: string | null,
};

/**
 *  The project's source manifest resolved through the window's vault index, with the exact text
 *  the agent receives (the project home's "Preview manifest").
 */
export type ManifestPreview = {
	manifest: Manifest,
	text: string,
};

export type PermissionDecision = "allow" | "deny";

export type PermissionPersist = "session" | "project" | "accept-edits";

export type PermissionResolution = "allowed" | "denied" | "cancelled";

export type PermissionRules = {
	allow: string[],
	deny: string[],
};

/**
 *  [`ProjectInfo`] (the shared contract) plus what the contract has no field for. Serialises as
 *  a superset of `ProjectInfo`, so the typed client can read it as one.
 */
export type ProjectDetail = {
	/**
	 *  Entries of the inclusion/exclusion lists whose shape is not recognised (shown as warning
	 *  rows, never dropped or rewritten).
	 */
	unsupported: string[],
	webUrls: string[],
	youtubeUrls: string[],
	/**  `writer-agent-mode` (`manual` or `acceptEdits`), when set. */
	agentMode: string | null,
	/**  Malformed values found in `project.md`. */
	warnings: string[],
} & ProjectInfo;

export type ProjectInfo = {
	path: string,
	id: string,
	name: string,
	description: string,
	createdAt: number | null,
	lastUsedAt: number | null,
	archivedAt: number | null,
	inclusions: ProjectSource[],
	exclusions: ProjectSource[],
	hasAgentsMd: boolean,
	hasClaudeMd: boolean,
};

export type ProjectSource = { kind: "folder"; path: string; raw: string } | { kind: "note"; path: string; raw: string } | { kind: "tag"; tag: string; raw: string } | { kind: "property"; name: string; value: string | null; raw: string } | { kind: "url"; url: string; raw: string };

/**  Partial update of `project.md`; only `Some` fields are written. */
export type ProjectUpdate = {
	name?: string | null,
	description?: string | null,
	inclusions?: string[] | null,
	exclusions?: string[] | null,
	webUrls?: string[] | null,
	youtubeUrls?: string[] | null,
	/**  `Some("")` removes the key. */
	agentMode?: string | null,
	touchLastUsed?: boolean,
};

export type RegenerateOutcome = { status: "done"; summary: ChatSummary } | { status: "refused"; reason: RegenerateRefusal };

/**  Why "Regenerate title" did nothing; the history list words each one. */
export type RegenerateRefusal = 
/**  No `claude` program was found. */
"no-binary" | 
/**  The chat has no assistant reply yet. */
"no-reply" | 
/**  The call failed or answered junk; the old title stays. */
"failed";

export type ReplaySeed = {
	/**  Text to put in front of the first message of the new session. */
	text: string,
	turnsIncluded: number,
	turnsTotal: number,
	estimatedTokens: number,
};

/**  Reply item of `agent_revert_changes`, one per requested path. */
export type RevertOutcome = {
	path: string,
	result: RevertResult,
	message?: string | null,
};

export type RevertResult = "reverted" | "changed-since" | "unavailable" | "failed";

export type SessionEndReason = "exit" | "killed" | "closed" | "vault-switched";

export type SnapshotReply = {
	state: AgentSessionState,
	events: AgentEventEnvelope[],
};

export type StartedIds = {
	chatId: string,
	sessionId: string,
};

export type ThinkingPhase = "start" | "delta" | "end";

/**
 *  Who chose a chat's title: nobody yet (the first message, cut), the automatic titler, or the
 *  user (a rename always wins and is never overwritten).
 */
export type TitleSource = "none" | "auto" | "user";

export type ToolOutcome = "ok" | "error" | "rejected";

/**  Reply of `agent_turn_changes`: the summary plus every diff. */
export type TurnChanges = {
	turnId: string,
	files: FileChange[],
	bash?: boolean,
};

export type TurnChangesSummary = {
	/**  Opaque; unique per app run, so a stored summary never matches a later snapshot by accident. */
	turnId: string,
	files: FileChangeSummary[],
	/**  A shell command ran in the turn: its side effects are not tracked. */
	bash?: boolean,
};

export type TurnFinishReason = "completed" | "interrupted" | "error" | "max-turns" | "budget";

/**  Whether "Undo" can run now. */
export type UndoState = "available" | 
/**  The file differs from how the turn left it: Undo would clobber newer edits. */
"changed-since" | 
/**  No pre-turn copy (too large, binary, outside the vault, a link). */
"unavailable" | "reverted";

export type UsageScope = "message" | "turn";
